from starlette.middleware.base import BaseHTTPMiddleware


JS = r'''(()=>{
'use strict';
const ID='ocReleaseProduction';let data=null,busy=false,timer=null;const expanded=new Set();
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const call=(path,opt)=>window.api(path,opt);const toast=m=>typeof window.showToast==='function'?window.showToast(String(m)):console.info(m);
function page(){const body=document.getElementById('moduleBody');if(!body)return null;const t=body.textContent||'';return t.includes('Read & understand')&&t.includes('Edit / organize')?body:null}
function styles(){if(document.getElementById('oc-release-style'))return;const s=document.createElement('style');s.id='oc-release-style';s.textContent=`
#${ID}{margin-top:18px}.oc-rel-head{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;flex-wrap:wrap}.oc-rel-head p{margin:6px 0 0;max-width:820px;opacity:.72}.oc-rel-badges,.oc-rel-provider-list{display:flex;gap:7px;flex-wrap:wrap}.oc-rel-badge,.oc-rel-provider-chip{padding:6px 9px;border-radius:999px;background:var(--surface-2,rgba(255,255,255,.06));font-size:11px}.oc-rel-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:14px}.oc-rel-control{display:grid;gap:7px;padding:12px;border:1px solid var(--border,rgba(255,255,255,.1));border-radius:13px}.oc-rel-control small{opacity:.68}.oc-rel-control select,.oc-rel-control input[type=number]{width:100%;min-height:38px;border-radius:9px;padding:7px 9px;background:var(--surface-2,rgba(255,255,255,.05));color:inherit;border:1px solid var(--border,rgba(255,255,255,.14))}.oc-rel-lock{padding:9px;border-radius:9px;background:var(--surface-2,rgba(255,255,255,.05));font-size:12px}.oc-rel-check{display:flex;align-items:center;justify-content:space-between;gap:10px}.oc-rel-check input{width:20px;height:20px}.oc-rel-warning{margin-top:12px;padding:10px 12px;border-radius:10px;background:rgba(245,158,11,.1);border:1px solid rgba(245,158,11,.25);font-size:12px}.oc-rel-list{margin-top:16px;display:grid;gap:9px}.oc-rel-entry{display:grid;gap:8px}.oc-rel-row{padding:12px;border:1px solid var(--border,rgba(255,255,255,.1));border-radius:13px;display:grid;grid-template-columns:minmax(0,1.5fr) minmax(110px,.6fr) minmax(0,1fr);gap:10px;align-items:center}.oc-rel-row small{display:block;opacity:.65;margin-top:3px;word-break:break-word}.oc-rel-actions{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}.oc-rel-actions button{min-height:34px}.oc-rel-empty{padding:16px;text-align:center;opacity:.7}.oc-rel-provider{margin-top:12px;display:grid;gap:8px;font-size:12px}.oc-rel-provider-chip strong{margin-right:5px}.oc-rel-evidence{padding:12px;border:1px solid var(--border,rgba(255,255,255,.1));border-radius:13px;background:var(--surface-2,rgba(255,255,255,.035));display:grid;gap:8px}.oc-rel-evidence-head{display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap}.oc-rel-evidence-list{display:grid;gap:7px}.oc-rel-event{padding:9px 10px;border-radius:10px;border:1px solid var(--border,rgba(255,255,255,.08));display:grid;gap:4px}.oc-rel-event-top{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.oc-rel-event-kind{font-size:11px;padding:3px 6px;border-radius:999px;background:rgba(255,255,255,.06)}.oc-rel-event small{opacity:.68;word-break:break-word}.oc-rel-metrics{display:flex;gap:8px;flex-wrap:wrap;font-size:11px}.oc-rel-metric{padding:4px 6px;border-radius:7px;background:rgba(255,255,255,.05)}.oc-rel-alert{font-size:11px;padding:4px 6px;border-radius:7px;background:rgba(245,158,11,.1)}@media(max-width:900px){.oc-rel-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.oc-rel-row{grid-template-columns:1fr 1fr}.oc-rel-actions{grid-column:1/-1;justify-content:flex-start}}@media(max-width:600px){.oc-rel-grid,.oc-rel-row{grid-template-columns:1fr}.oc-rel-actions{grid-column:auto}.oc-rel-head{display:grid}.oc-rel-evidence-head{display:grid}}
`;document.head.appendChild(s)}
function opt(v,l,c){return `<option value="${esc(v)}" ${String(c)===String(v)?'selected':''}>${esc(l)}</option>`}
function ctl(label,key,inner,help=''){return `<label class="oc-rel-control"><strong>${esc(label)}</strong>${inner}${help?`<small>${esc(help)}</small>`:''}</label>`}
function chk(label,key,v,help=''){return `<label class="oc-rel-control oc-rel-check"><span><strong style="display:block">${esc(label)}</strong>${help?`<small>${esc(help)}</small>`:''}</span><input type="checkbox" data-rel-key="${esc(key)}" ${v?'checked':''}></label>`}
function locked(label,value,help){return `<div class="oc-rel-control"><strong>${esc(label)}</strong><div class="oc-rel-lock">${esc(value)}</div><small>${esc(help)}</small></div>`}
function action(id,name,label,danger=false){return `<button type="button" class="oc-button ${danger?'danger':''}" data-rel-action="${esc(name)}" data-rel-id="${esc(id)}">${esc(label)}</button>`}
function metric(label,value){return `<span class="oc-rel-metric"><strong>${esc(label)}</strong> ${esc(value)}</span>`}
function telemetryMetrics(e){const m=e&&e.metadata&&typeof e.metadata==='object'?e.metadata:{};if(e.kind==='production_provider_telemetry'){const out=[];if(Number.isFinite(Number(m.request_count)))out.push(metric('Requests',Number(m.request_count)));if(Number.isFinite(Number(m.server_error_count)))out.push(metric('5xx',Number(m.server_error_count)));if(Number.isFinite(Number(m.error_rate)))out.push(metric('Error rate',`${(Number(m.error_rate)*100).toFixed(2)}%`));if(Number.isFinite(Number(m.p95_latency_ms)))out.push(metric('p95',`${Number(m.p95_latency_ms).toFixed(1)} ms`));if(Number.isFinite(Number(m.window_seconds)))out.push(metric('Window',`${Number(m.window_seconds)}s`));return out.join('')}if(e.kind==='production_provider_telemetry_error'){return `<span class="oc-rel-alert">Telemetry unavailable · ${esc(m.error_type||'provider error')} · no rollback authority</span>`}if(e.kind==='production_monitor_error'){return `<span class="oc-rel-alert">Monitor could not prove health · ${esc(m.error_type||'error')}</span>`}if(e.kind==='production_monitor_observation'){const available=m.provider_telemetry_available===true?'telemetry supported':'telemetry not configured';const observed=m.provider_telemetry_observed===true?'sampled':'not sampled';return metric('Monitor',`${available} · ${observed}`)}return ''}
function evidenceTimeline(r){const items=Array.isArray(r.evidence)?r.evidence.slice(-10).reverse():[];if(!items.length)return '<div class="oc-rel-empty">No persisted release evidence yet.</div>';return `<div class="oc-rel-evidence-list">${items.map(e=>`<div class="oc-rel-event"><div class="oc-rel-event-top"><span class="oc-rel-event-kind">${esc(e.kind||'evidence')}</span>${e.trusted?'<span class="oc-rel-badge">Trusted</span>':''}<small>${esc(e.created_at||'')}</small></div><div>${esc(e.summary||'Release evidence')}</div>${telemetryMetrics(e)?`<div class="oc-rel-metrics">${telemetryMetrics(e)}</div>`:''}</div>`).join('')}</div>`}
function detail(r){return `<div class="oc-rel-evidence"><div class="oc-rel-evidence-head"><div><strong>Monitoring & evidence history</strong><small>Persisted trusted release evidence only. Provider telemetry is sanitized aggregate data; raw logs are never displayed or stored here.</small></div><span class="oc-rel-badge">${esc((r.evidence||[]).length)} events</span></div>${evidenceTimeline(r)}</div>`}
function rows(items){if(!Array.isArray(items)||!items.length)return '<div class="oc-rel-empty">No qualified engineering candidate has entered release control yet.</div>';return items.slice(0,20).map(r=>{let buttons='';if(r.approval_required&&!r.approved_by&&!['succeeded','failed','cancelled','rolled_back'].includes(r.status))buttons+=action(r.id,'approve','Approve');if(['planned','awaiting_approval'].includes(r.status))buttons+=action(r.id,'preview','Preview');if(r.status==='preview_qualified')buttons+=action(r.id,'promote','Promote');if(r.status==='rollback_recommended')buttons+=action(r.id,'rollback','Rollback',true);if(!['succeeded','failed','cancelled','rolled_back','promoting','rolling_back'].includes(r.status))buttons+=action(r.id,'cancel','Cancel');const hasEvidence=Array.isArray(r.evidence)&&r.evidence.length>0;if(hasEvidence)buttons+=`<button type="button" class="oc-button" data-rel-details="${esc(r.id)}">${expanded.has(String(r.id))?'Hide evidence':'Evidence'}</button>`;const incident=r.status==='rollback_recommended'?'<span class="oc-rel-alert">Production incident requires owner decision</span>':'';return `<section class="oc-rel-entry"><article class="oc-rel-row"><div><strong>${esc(r.id)}</strong><small>Candidate ${esc(String(r.candidate_revision||'').slice(0,12))}… · ${esc(r.provider)} · ${esc(r.target)}</small><small>${esc(r.preview_url||r.production_url||'No deployment URL yet')}</small>${incident}</div><div><strong>${esc(r.status)}</strong><small>${esc(r.risk_class)} risk${r.approval_required?' · approval governed':''}</small></div><div class="oc-rel-actions">${buttons||'<small>No owner action required.</small>'}</div></article>${expanded.has(String(r.id))?detail(r):''}</section>`}).join('')}
function providerChips(x){const providers=Array.isArray(x.providers)?x.providers:[];const caps=x.provider_capabilities&&typeof x.provider_capabilities==='object'?x.provider_capabilities:{};if(!providers.length)return '<span class="oc-rel-provider-chip">none — qualified candidates remain engineering-qualified but are not deployable from this host.</span>';return providers.map(name=>{const c=caps[name]||{};const labels=[];if(c.production_observation)labels.push('deployment observation');if(c.production_telemetry)labels.push('sanitized telemetry');return `<span class="oc-rel-provider-chip"><strong>${esc(name)}</strong>${esc(labels.length?labels.join(' · '):'configured')}</span>`}).join('')}
function panel(x){const p=x.policy||{};return `<section class="oc-panel" id="${ID}"><div class="oc-rel-head"><div><strong>Release Control</strong><p>Govern how an exact, independently qualified engineering candidate may move through Preview, production smoke checks, canary monitoring, provider telemetry, Promote, Rollback and Cancel actions. Release authority is separate from Engineering Autonomy.</p></div><div class="oc-rel-badges"><span class="oc-rel-badge">Exact SHA bound</span><span class="oc-rel-badge">Low-risk auto only</span><span class="oc-rel-badge">Sensitive approval locked</span><span class="oc-rel-badge">No Body activation</span></div></div><div class="oc-rel-grid">
${ctl('Release mode','mode',`<select data-rel-key="mode">${opt('off','Off',p.mode)}${opt('preview_only','Preview only',p.mode)}${opt('approval_required','Approval required',p.mode)}${opt('auto_low_risk','Auto low-risk',p.mode)}</select>`,'Auto low-risk applies only to low-risk, non-sensitive releases.')}
${locked('Automatic risk ceiling','Low','Medium, high and critical releases always require explicit owner approval.')}
${locked('Sensitive surfaces','Owner approval required','Authentication, security, billing, database, provider, runtime, owner-permission, release/deploy, Body and evolution surfaces cannot auto-promote.')}
${ctl('Canary minimum requests','canary_min_requests',`<input type="number" min="1" max="100000" value="${esc(p.canary_min_requests??20)}" data-rel-key="canary_min_requests">`)}
${ctl('Max error-rate regression','canary_max_error_rate_regression',`<input type="number" min="0" max="1" step="0.01" value="${esc(p.canary_max_error_rate_regression??0.05)}" data-rel-key="canary_max_error_rate_regression">`)}
${ctl('Max p95 latency ratio','canary_max_latency_ratio',`<input type="number" min="1" max="100" step="0.05" value="${esc(p.canary_max_latency_ratio??1.35)}" data-rel-key="canary_max_latency_ratio">`)}
${ctl('Monitoring observation limit','max_monitoring_observations',`<input type="number" min="1" max="100000" value="${esc(p.max_monitoring_observations??1000)}" data-rel-key="max_monitoring_observations">`,'Bounds durable production monitor observations per release.')}
${chk('Allow production','allow_production',p.allow_production!==false)}
${chk('Require preview','require_preview',p.require_preview!==false)}
${chk('Require exact-revision evidence','require_exact_revision_evidence',p.require_exact_revision_evidence!==false)}
${chk('Require production smoke','require_production_smoke',p.require_production_smoke!==false)}
${chk('Require canary','require_canary',p.require_canary!==false)}
${chk('Permit explicitly confirmed rollback','allow_automatic_rollback',!!p.allow_automatic_rollback,'This only permits the rollback action after an explicit owner confirmation; it never creates silent automatic rollback.')}
</div><div class="oc-rel-warning">Production promotion and rollback require a trusted admin device and fresh owner verification when the plan is approval-gated. A canary or provider-telemetry regression can recommend rollback and open Canonical Work, but it cannot silently roll production back.</div><div class="oc-rel-provider"><strong>Configured provider monitoring</strong><div class="oc-rel-provider-list">${providerChips(x)}</div></div><div class="oc-rel-list"><div class="oc-rel-head"><strong>Release ledger</strong><button type="button" class="oc-button" data-rel-refresh>Refresh</button></div>${rows(x.releases)}</div></section>`}
async function load(force=false){if(busy&&!force)return;busy=true;try{data=await call('/owner/release/summary');mount()}catch(e){console.warn('Release control unavailable',e);const old=document.getElementById(ID);if(old)old.innerHTML='<strong>Release Control</strong><p>Release control is unavailable on this host.</p>'}finally{busy=false}}
async function save(el){const key=el.dataset.relKey;if(!key)return;let value=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;el.disabled=true;try{const r=await call('/owner/release/policy',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({[key]:value})});data={...(data||{}),policy:r.policy};toast('Release policy saved.');mount()}catch(e){toast(e.message||'Fresh owner verification may be required.');await load(true)}finally{el.disabled=false}}
async function act(button){const id=button.dataset.relId,name=button.dataset.relAction;if(!id||!name)return;let body;if(name==='rollback'){if(!window.confirm('Rollback production to the bound base revision?'))return;body={confirm:true}}if(name==='cancel'){const reason=window.prompt('Reason for cancelling this release:','Owner cancelled release');if(!reason)return;body={reason}}button.disabled=true;try{await call(`/owner/release/${encodeURIComponent(id)}/${name}`,{method:'POST',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});toast(`Release action ${name} completed.`);await load(true)}catch(e){toast(e.message||`Release action ${name} failed.`)}finally{button.disabled=false}}
function toggle(id){id=String(id||'');if(!id)return;if(expanded.has(id))expanded.delete(id);else expanded.add(id);mount()}
function bind(root){root.querySelectorAll('[data-rel-key]').forEach(el=>el.addEventListener('change',()=>save(el)));root.querySelector('[data-rel-refresh]')?.addEventListener('click',()=>load(true));root.querySelectorAll('[data-rel-action]').forEach(el=>el.addEventListener('click',()=>act(el)));root.querySelectorAll('[data-rel-details]').forEach(el=>el.addEventListener('click',()=>toggle(el.dataset.relDetails)))}
function mount(){styles();const body=page();if(!body)return;let cur=document.getElementById(ID);if(!data){if(!cur){cur=document.createElement('section');cur.id=ID;cur.className='oc-panel';cur.innerHTML='<strong>Release Control</strong><p>Loading governed release controls…</p>';body.appendChild(cur)}load();return}const h=document.createElement('div');h.innerHTML=panel(data);const fresh=h.firstElementChild;if(cur)cur.replaceWith(fresh);else body.appendChild(fresh);bind(fresh);if(!timer)timer=setInterval(()=>{if(page())load(true)},10000)}
const observer=new MutationObserver(()=>{if(page()&&!document.getElementById(ID))mount()});observer.observe(document.documentElement,{childList:true,subtree:true});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount);else mount();
})();'''


class OwnerReleaseUiMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request, call_next):
        response = await call_next(request)
        if request.url.path not in {"/iphone", "/iphone/"} or response.status_code != 200:
            return response
        if "text/html" not in response.headers.get("content-type", ""):
            return response
        body = b""
        async for chunk in response.body_iterator:
            body += chunk
        text = body.decode("utf-8")
        marker = "</body>"
        script = '<script src="/iphone/owner-release-ui.js"></script>'
        if marker in text and script not in text:
            text = text.replace(marker, script + marker, 1)
        headers = {key: value for key, value in response.headers.items() if key.lower() not in {"content-length", "content-encoding"}}
        return Response(text, status_code=response.status_code, headers=headers, media_type="text/html")


def owner_release_ui_router() -> APIRouter:
    router = APIRouter()

    @router.get("/iphone/owner-release-ui.js", include_in_schema=False)
    def owner_release_js():
        return Response(JS, media_type="application/javascript", headers={"Cache-Control": "no-cache"})

    return router
